CREATE TABLE academic_years (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), name VARCHAR(100) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, is_current BOOLEAN NOT NULL DEFAULT FALSE, status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,name));
CREATE UNIQUE INDEX uq_current_academic_year ON academic_years(tenant_id) WHERE is_current=TRUE;
CREATE TABLE classes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), name VARCHAR(100) NOT NULL, display_order INT NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(tenant_id,name));
CREATE TABLE streams (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), name VARCHAR(100) NOT NULL, code VARCHAR(50), active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(tenant_id,name));
CREATE TABLE subjects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), name VARCHAR(150) NOT NULL, code VARCHAR(50), active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(tenant_id,name));
CREATE TABLE class_streams (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), academic_year_id UUID NOT NULL REFERENCES academic_years(id), class_id UUID NOT NULL REFERENCES classes(id), stream_id UUID NOT NULL REFERENCES streams(id), UNIQUE(tenant_id,academic_year_id,class_id,stream_id));
CREATE TABLE class_subjects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), academic_year_id UUID NOT NULL REFERENCES academic_years(id), class_id UUID NOT NULL REFERENCES classes(id), subject_id UUID NOT NULL REFERENCES subjects(id), UNIQUE(tenant_id,academic_year_id,class_id,subject_id));
CREATE TABLE batches (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), academic_year_id UUID NOT NULL REFERENCES academic_years(id), class_id UUID NOT NULL REFERENCES classes(id), stream_id UUID REFERENCES streams(id), name VARCHAR(150) NOT NULL, code VARCHAR(50), capacity INT, status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE', UNIQUE(tenant_id,academic_year_id,name));
CREATE TABLE classrooms (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), name VARCHAR(100) NOT NULL, room_code VARCHAR(50), capacity INT, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(tenant_id,name));
CREATE TABLE students (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), admission_number VARCHAR(100) NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100), email VARCHAR(255), phone VARCHAR(30), date_of_birth DATE, gender VARCHAR(30), status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE', address TEXT, profile_photo_url TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,admission_number));
CREATE TABLE parents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100), email VARCHAR(255), phone VARCHAR(30), occupation VARCHAR(150), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE student_parents (student_id UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE, parent_id UUID NOT NULL REFERENCES parents(id) ON DELETE CASCADE, relation VARCHAR(50), is_primary BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY(student_id,parent_id));
CREATE TABLE enrollments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), student_id UUID NOT NULL REFERENCES students(id), academic_year_id UUID NOT NULL REFERENCES academic_years(id), class_id UUID NOT NULL REFERENCES classes(id), stream_id UUID REFERENCES streams(id), batch_id UUID NOT NULL REFERENCES batches(id), status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE', enrolled_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,student_id,academic_year_id));
CREATE TABLE teachers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), user_id UUID REFERENCES users(id), employee_code VARCHAR(100), first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100), email VARCHAR(255), phone VARCHAR(30), status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,employee_code));
CREATE TABLE teacher_batch_assignments (teacher_id UUID NOT NULL REFERENCES teachers(id) ON DELETE CASCADE, batch_id UUID NOT NULL REFERENCES batches(id) ON DELETE CASCADE, PRIMARY KEY(teacher_id,batch_id));
CREATE TABLE teacher_subjects (teacher_id UUID NOT NULL REFERENCES teachers(id) ON DELETE CASCADE, subject_id UUID NOT NULL REFERENCES subjects(id) ON DELETE CASCADE, PRIMARY KEY(teacher_id,subject_id));
CREATE INDEX idx_academic_tenant ON academic_years(tenant_id); CREATE INDEX idx_batches_tenant_year ON batches(tenant_id,academic_year_id); CREATE INDEX idx_enrollments_tenant_batch ON enrollments(tenant_id,batch_id); CREATE INDEX idx_students_tenant_status ON students(tenant_id,status);
CREATE TABLE attendance_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), batch_id UUID NOT NULL REFERENCES batches(id), subject_id UUID REFERENCES subjects(id), teacher_id UUID REFERENCES teachers(id), session_date DATE NOT NULL, start_time TIME, end_time TIME, status VARCHAR(30) NOT NULL DEFAULT 'OPEN');
CREATE TABLE attendance_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), session_id UUID NOT NULL REFERENCES attendance_sessions(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES students(id), status VARCHAR(20) NOT NULL, marked_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(session_id,student_id));
CREATE TABLE timetable_entries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), batch_id UUID NOT NULL REFERENCES batches(id), subject_id UUID REFERENCES subjects(id), teacher_id UUID REFERENCES teachers(id), classroom_id UUID REFERENCES classrooms(id), day_of_week INT NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL);
CREATE TABLE assignments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), batch_id UUID NOT NULL REFERENCES batches(id), teacher_id UUID REFERENCES teachers(id), title VARCHAR(200) NOT NULL, description TEXT, due_at TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE assignment_submissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), assignment_id UUID NOT NULL REFERENCES assignments(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES students(id), submitted_at TIMESTAMP, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', score NUMERIC(8,2), feedback TEXT, UNIQUE(assignment_id,student_id));
CREATE TABLE exams (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), academic_year_id UUID NOT NULL REFERENCES academic_years(id), name VARCHAR(200) NOT NULL, exam_type VARCHAR(50) NOT NULL, starts_at TIMESTAMP, ends_at TIMESTAMP, status VARCHAR(30) NOT NULL DEFAULT 'DRAFT');
CREATE TABLE exam_subjects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), exam_id UUID NOT NULL REFERENCES exams(id) ON DELETE CASCADE, subject_id UUID NOT NULL REFERENCES subjects(id), max_marks NUMERIC(8,2) NOT NULL, pass_marks NUMERIC(8,2), negative_marking NUMERIC(8,2) DEFAULT 0, UNIQUE(exam_id,subject_id));
CREATE TABLE questions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), subject_id UUID REFERENCES subjects(id), text TEXT NOT NULL, question_type VARCHAR(40) NOT NULL, difficulty VARCHAR(30), topic VARCHAR(150), chapter VARCHAR(150), marks NUMERIC(8,2) NOT NULL DEFAULT 1, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE question_options (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), question_id UUID NOT NULL REFERENCES questions(id) ON DELETE CASCADE, option_text TEXT NOT NULL, is_correct BOOLEAN NOT NULL DEFAULT FALSE, display_order INT NOT NULL DEFAULT 0);
CREATE TABLE exam_attempts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), exam_id UUID NOT NULL REFERENCES exams(id), student_id UUID NOT NULL REFERENCES students(id), started_at TIMESTAMP, submitted_at TIMESTAMP, score NUMERIC(8,2), status VARCHAR(30) NOT NULL DEFAULT 'IN_PROGRESS', UNIQUE(exam_id,student_id));
CREATE TABLE attempt_answers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id UUID NOT NULL REFERENCES exam_attempts(id) ON DELETE CASCADE, question_id UUID NOT NULL REFERENCES questions(id), answer_text TEXT, is_correct BOOLEAN, marks_awarded NUMERIC(8,2));
CREATE TABLE results (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), exam_id UUID NOT NULL REFERENCES exams(id), student_id UUID NOT NULL REFERENCES students(id), total_marks NUMERIC(10,2), obtained_marks NUMERIC(10,2), percentage NUMERIC(6,2), rank INT, status VARCHAR(30) NOT NULL DEFAULT 'DRAFT', published_at TIMESTAMP, UNIQUE(exam_id,student_id));
CREATE TABLE result_subjects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), result_id UUID NOT NULL REFERENCES results(id) ON DELETE CASCADE, subject_id UUID NOT NULL REFERENCES subjects(id), max_marks NUMERIC(8,2), obtained_marks NUMERIC(8,2), UNIQUE(result_id,subject_id));
CREATE TABLE fee_plans (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), name VARCHAR(150) NOT NULL, total_amount NUMERIC(12,2) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE fee_installments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), fee_plan_id UUID NOT NULL REFERENCES fee_plans(id) ON DELETE CASCADE, name VARCHAR(150) NOT NULL, amount NUMERIC(12,2) NOT NULL, due_date DATE NOT NULL, sequence_no INT NOT NULL);
CREATE TABLE invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), student_id UUID NOT NULL REFERENCES students(id), installment_id UUID REFERENCES fee_installments(id), invoice_number VARCHAR(100) NOT NULL, amount NUMERIC(12,2) NOT NULL, paid_amount NUMERIC(12,2) NOT NULL DEFAULT 0, due_date DATE NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'UNPAID', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,invoice_number));
CREATE TABLE payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), invoice_id UUID NOT NULL REFERENCES invoices(id), amount NUMERIC(12,2) NOT NULL, gateway VARCHAR(50), gateway_transaction_id VARCHAR(200), status VARCHAR(30) NOT NULL DEFAULT 'PENDING', paid_at TIMESTAMP, idempotency_key VARCHAR(200), UNIQUE(tenant_id,gateway,gateway_transaction_id));
CREATE TABLE receipts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), payment_id UUID NOT NULL UNIQUE REFERENCES payments(id), receipt_number VARCHAR(100) NOT NULL UNIQUE, issued_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE expenses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), category VARCHAR(100) NOT NULL, description TEXT, amount NUMERIC(12,2) NOT NULL, expense_date DATE NOT NULL);
CREATE TABLE payroll (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), teacher_id UUID REFERENCES teachers(id), month DATE NOT NULL, gross_amount NUMERIC(12,2) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'DRAFT');
CREATE TABLE conversations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), type VARCHAR(30) NOT NULL, title VARCHAR(200), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE conversation_members (conversation_id UUID NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(conversation_id,user_id));
CREATE TABLE messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), conversation_id UUID NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sender_user_id UUID NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, read_at TIMESTAMP);
CREATE TABLE notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), user_id UUID NOT NULL REFERENCES users(id), type VARCHAR(50) NOT NULL, title VARCHAR(200) NOT NULL, body TEXT, read_at TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE video_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), host_user_id UUID NOT NULL REFERENCES users(id), title VARCHAR(200), provider VARCHAR(50), external_room_id VARCHAR(200), starts_at TIMESTAMP, ends_at TIMESTAMP, status VARCHAR(30) NOT NULL DEFAULT 'SCHEDULED');
CREATE TABLE video_participants (session_id UUID NOT NULL REFERENCES video_sessions(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id), role VARCHAR(30), PRIMARY KEY(session_id,user_id));
CREATE TABLE leads (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), name VARCHAR(200) NOT NULL, phone VARCHAR(30), email VARCHAR(255), source VARCHAR(100), stage VARCHAR(50) NOT NULL DEFAULT 'ENQUIRY', counsellor_user_id UUID REFERENCES users(id), lost_reason VARCHAR(200), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE lead_activities (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), lead_id UUID NOT NULL REFERENCES leads(id) ON DELETE CASCADE, user_id UUID REFERENCES users(id), type VARCHAR(50) NOT NULL, notes TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE follow_ups (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), lead_id UUID REFERENCES leads(id), assigned_user_id UUID REFERENCES users(id), due_at TIMESTAMP NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', notes TEXT);
CREATE TABLE tickets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), created_by UUID REFERENCES users(id), assigned_to UUID REFERENCES users(id), subject VARCHAR(200) NOT NULL, description TEXT, priority VARCHAR(30) NOT NULL DEFAULT 'NORMAL', status VARCHAR(30) NOT NULL DEFAULT 'OPEN', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ticket_messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), ticket_id UUID NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, user_id UUID REFERENCES users(id), body TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE automation_rules (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), name VARCHAR(200) NOT NULL, trigger_event VARCHAR(100) NOT NULL, active BOOLEAN NOT NULL DEFAULT FALSE, cooldown_seconds INT DEFAULT 0, max_depth INT DEFAULT 5, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE automation_conditions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), rule_id UUID NOT NULL REFERENCES automation_rules(id) ON DELETE CASCADE, field_name VARCHAR(200) NOT NULL, operator VARCHAR(50) NOT NULL, comparison_value TEXT, group_no INT NOT NULL DEFAULT 0);
CREATE TABLE automation_actions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), rule_id UUID NOT NULL REFERENCES automation_rules(id) ON DELETE CASCADE, action_type VARCHAR(100) NOT NULL, action_config JSONB NOT NULL DEFAULT '{}'::jsonb, action_order INT NOT NULL DEFAULT 0);
CREATE TABLE automation_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), rule_id UUID NOT NULL REFERENCES automation_rules(id), event_id VARCHAR(200), status VARCHAR(30) NOT NULL, attempt_count INT NOT NULL DEFAULT 0, error_message TEXT, started_at TIMESTAMP, completed_at TIMESTAMP, UNIQUE(rule_id,event_id));
CREATE TABLE audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID REFERENCES tenants(id), user_id UUID REFERENCES users(id), action VARCHAR(100) NOT NULL, entity_type VARCHAR(100), entity_id UUID, request_id VARCHAR(100), metadata JSONB, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE outbox_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID REFERENCES tenants(id), aggregate_type VARCHAR(100) NOT NULL, aggregate_id UUID, event_type VARCHAR(150) NOT NULL, payload JSONB NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', attempts INT NOT NULL DEFAULT 0, available_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, published_at TIMESTAMP);
CREATE TABLE documents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), entity_type VARCHAR(100) NOT NULL, entity_id UUID NOT NULL, file_name VARCHAR(255) NOT NULL, object_key TEXT NOT NULL, content_type VARCHAR(100), size_bytes BIGINT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tenant_settings (tenant_id UUID PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE, settings JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX idx_notifications_user_unread ON notifications(tenant_id,user_id,read_at); CREATE INDEX idx_messages_conversation_created ON messages(conversation_id,created_at); CREATE INDEX idx_invoices_due ON invoices(tenant_id,due_date,status); CREATE INDEX idx_leads_stage ON leads(tenant_id,stage); CREATE INDEX idx_automation_runs_status ON automation_runs(tenant_id,status); CREATE INDEX idx_outbox_pending ON outbox_events(status,available_at);
INSERT INTO permissions(code,description) VALUES
('academics.read','View academic configuration'),('academics.manage','Manage academic configuration'),('students.update','Update students'),('students.delete','Archive students'),('teachers.create','Create teachers'),('teachers.update','Update teachers'),('teachers.delete','Archive teachers'),('attendance.manage','Manage attendance'),('timetable.manage','Manage timetable'),('homework.manage','Manage homework'),('exams.manage','Manage exams'),('questions.manage','Manage question bank'),('results.manage','Manage results'),('finance.manage','Manage finance'),('communication.send','Send communication'),('admissions.manage','Manage admissions'),('support.manage','Manage support'),('automation.manage','Manage automations'),('reports.read','View reports'),('audit.read','View audit logs') ON CONFLICT(code) DO NOTHING;
